<?php
$done=false;$err=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$h=$_POST['host'];$n=$_POST['name'];$u=$_POST['user'];$p=$_POST['pass'];$pdo=new PDO("mysql:host=$h;charset=utf8mb4",$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec("CREATE DATABASE IF NOT EXISTS `$n` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo->exec("USE `$n`");$sql=["CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE,password_hash VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)","CREATE TABLE IF NOT EXISTS settings(`key` VARCHAR(100) PRIMARY KEY,value TEXT)","CREATE TABLE IF NOT EXISTS collections(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),slug VARCHAR(180),description TEXT,image VARCHAR(255),sort_order INT DEFAULT 0,visible TINYINT DEFAULT 1)","CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80),name VARCHAR(180),slug VARCHAR(200),collection_id INT NULL,description TEXT,size VARCHAR(100),stock INT DEFAULT 0,price VARCHAR(100),image VARCHAR(255),type VARCHAR(20) DEFAULT 'normal',visible TINYINT DEFAULT 1,featured TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)"];foreach($sql as $q)$pdo->exec($q);$st=$pdo->prepare('SELECT COUNT(*) FROM admins');if(!$st->execute()||!$st->fetchColumn()){$x=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$x->execute([$_POST['admin'],password_hash($_POST['adminpass'],PASSWORD_DEFAULT)]);} $defaults=['site_name'=>'Yusuf Seçilmiş Carpet','hero_title'=>'Toptan Halıda Güçlü Tedarik, Güçlü İş Ortaklığı','hero_text'=>'İhracata ve toptan alıma hazır koleksiyonlar.','phone'=>'+90 544 545 29 67','whatsapp'=>'905445452967','email'=>'yusufsecilmiscarpet@gmail.com','about'=>'Yusuf Seçilmiş Carpet; toptan, ihracat ve proje bazlı halı tedarikinde çözüm ortağınızdır.'];$q=$pdo->prepare('INSERT IGNORE INTO settings(`key`,value) VALUES(?,?)');foreach($defaults as $k=>$v)$q->execute([$k,$v]);$collections=['1000 Reeds','1500 Reeds','Flosh Polyester Modern','Bukle İskandinav','Kaymaz Taban','Polyester Klasik','Sisal Jüt','Tafting'];$q=$pdo->prepare('INSERT INTO collections(name,slug,sort_order) VALUES(?,?,?)');foreach($collections as $i=>$c)$q->execute([$c,preg_replace('/[^a-z0-9]+/','-',strtolower($c)),$i]);$done=true;}catch(Throwable $x){$err=$x->getMessage();}}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>YSC Kurulum</title><style>body{background:#0b0b0b;color:#eee;font:16px Arial;max-width:650px;margin:60px auto;padding:20px}h1{color:#d7b46a}input{width:100%;padding:12px;margin:7px 0 15px;background:#181818;border:1px solid #444;color:#fff}button{padding:13px 22px;background:#d7b46a;border:0;font-weight:bold}.ok{padding:15px;background:#143b22}.err{padding:15px;background:#4a1515}</style></head><body><h1>YSC Carpet — Kurulum</h1><?php if($done):?><div class="ok">Kurulum tamamlandı. <a href="admin/login.php">Admin paneline gir</a></div><?php else:?><p>Hostingindeki MySQL bilgilerini gir.</p><?php if($err):?><div class="err"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post"><label>MySQL Host</label><input name="host" value="localhost"><label>Veritabanı adı</label><input name="name" value="ysc_carpet"><label>Kullanıcı</label><input name="user"><label>Şifre</label><input type="password" name="pass"><label>Admin kullanıcı</label><input name="admin" value="admin"><label>Admin şifresi</label><input type="password" name="adminpass" required><button>Kurulumu Başlat</button></form><?php endif;?></body></html>
